mapper.select:
SELECT s.id, s.member_id AS memberId, s.started_at AS startedAt, s.finished_at AS finishedAt,
       s.distance_m AS distanceM, s.tiles_revealed AS tilesRevealed, s.pois_found AS poisFound,
       s.xp_awarded AS xpAwarded, s.status
FROM roam_session s

     AND s.member_id = #{memberId} 
     AND s.status = #{status} 


ORDER BY s.id DESC
LIMIT #{limit}

SELECT f.member_id AS memberId, COUNT(1) AS revealedCells, MIN(f.first_revealed_at) AS firstRevealedAt, MAX(f.last_revealed_at) AS lastRevealedAt FROM roam_member_fog_cell f
AND f.member_id = #{memberId}
GROUP BY f.member_id ORDER BY revealedCells DESC, f.member_id LIMIT #{limit}

SELECT t.id, t.owner_type AS ownerType, t.owner_id AS ownerId, t.leader_member_id AS leaderMemberId, t.title,
       t.join_mode AS joinMode, t.max_members AS maxMembers, t.joined_count AS joinedCount, t.status,
       t.expire_time AS expireTime, t.create_time AS createTime,
       (SELECT COUNT(1) FROM play_team_member m WHERE m.team_id = t.id AND m.status = 1) AS activeMembers,
       (SELECT COUNT(1) FROM play_team_member m WHERE m.team_id = t.id AND m.status = 0) AS pendingMembers
FROM play_team t

     AND t.owner_type = #{ownerType} 
     AND t.owner_id = #{ownerId} 
     AND t.status = #{status} 

ORDER BY t.id DESC
LIMIT #{limit}

SELECT r.id, r.member_id AS memberId, r.activity_id AS activityId, r.topic_id AS topicId, r.run_state AS runState,
       r.elapsed_seconds AS elapsedSeconds, r.create_time AS createTime, r.update_time AS updateTime
FROM player_run_session r

     AND r.member_id = #{memberId} 
     AND r.topic_id = #{topicId} 
     AND r.run_state = #{runState} 

ORDER BY r.update_time DESC, r.id DESC
LIMIT #{limit}

SELECT g.id, g.activity_id AS activityId, g.topic_id AS topicId, g.node_id AS nodeId, g.template_id AS templateId,
       g.owner_type AS ownerType, g.owner_id AS ownerId, g.status, g.score, g.completed_units AS completedUnits,
       g.started_at AS startedAt, g.deadline_at AS deadlineAt, g.completed_at AS completedAt
FROM game_runtime_session g

     AND g.topic_id = #{topicId} 
     AND g.owner_type = #{ownerType} 
     AND g.owner_id = #{ownerId} 
     AND g.status = #{status} 

ORDER BY g.id DESC
LIMIT #{limit}
